//! The RNG against LuaJIT itself: `tests/fixtures/rng_luajit.json` holds the bit patterns the
//! game's own RNG functions produce under LuaJIT 2.1 (generated by
//! `scripts/luajit_rng_oracle.lua` from the local Balatro source). Every comparison is exact.

use std::collections::HashMap;
use std::path::PathBuf;

use jackdaw_core::lua;
use jackdaw_core::rng::{self, Rng, Tw223};
use serde_json::Value;

fn fixture() -> Value {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/rng_luajit.json");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).expect("valid JSON")
}

fn bits(v: &Value) -> u64 {
    u64::from_str_radix(v.as_str().expect("hex string"), 16).expect("hex")
}

fn num(v: &Value) -> f64 {
    f64::from_bits(bits(v))
}

fn arr(v: &Value) -> &Vec<Value> {
    v.as_array().expect("array")
}

#[test]
fn pseudohash_matches() {
    for case in arr(&fixture()["pseudohash"]) {
        let bytes: Vec<u8> = arr(&case["bytes"])
            .iter()
            .map(|b| b.as_u64().unwrap() as u8)
            .collect();
        let got = rng::pseudohash(&bytes);
        assert_eq!(
            got.to_bits(),
            bits(&case["hash"]),
            "pseudohash({:?})",
            String::from_utf8_lossy(&bytes)
        );
    }
}

#[test]
fn truncate13_matches() {
    for case in arr(&fixture()["truncate13"]) {
        let pair = arr(case);
        let x = num(&pair[0]);
        assert_eq!(
            lua::truncate13(x).to_bits(),
            bits(&pair[1]),
            "truncate13({x:e})"
        );
    }
}

#[test]
fn tostring_matches() {
    for case in arr(&fixture()["tostring"]) {
        let pair = arr(case);
        let x = num(&pair[0]);
        assert_eq!(
            lua::tostring_number(x),
            pair[1].as_str().unwrap(),
            "tostring({x:e})"
        );
    }
}

#[test]
fn seeded_draws_match() {
    for case in arr(&fixture()["seeded"]) {
        let d = num(&case["d"]);
        let mut tw = Tw223::seeded(d);
        for (i, want) in arr(&case["floats"]).iter().enumerate() {
            assert_eq!(tw.random().to_bits(), bits(want), "seed {d:e} draw {i}");
        }
        let ints: Vec<i64> = arr(&case["ints"])
            .iter()
            .map(|v| v.as_i64().unwrap())
            .collect();
        assert_eq!(tw.random_range(1, 52), ints[0], "seed {d:e} random(1, 52)");
        assert_eq!(tw.random_n(7), ints[1], "seed {d:e} random(7)");
        assert_eq!(
            tw.random_range(0, 1 << 30),
            ints[2],
            "seed {d:e} random(0, 2^30)"
        );
    }
}

#[test]
fn stream_sequences_match() {
    for run in arr(&fixture()["streams"]) {
        let seed = run["seed"].as_str().unwrap();
        let mut hashed = rng::pseudohash(seed.as_bytes());
        let mut preset = HashMap::new();
        for inj in arr(&run["inject"]) {
            let pair = arr(inj);
            match pair[0].as_str().unwrap() {
                "hashed_seed" => hashed = num(&pair[1]),
                stream => {
                    preset.insert(stream.to_owned(), num(&pair[1]));
                }
            }
        }
        assert_eq!(
            hashed.to_bits(),
            bits(&run["hashed_seed"]),
            "{seed}: hashed_seed"
        );
        let mut r = Rng::from_parts(seed.to_owned(), hashed, preset);
        for (i, op) in arr(&run["ops"]).iter().enumerate() {
            let op = arr(op);
            let key = op[1].as_str().unwrap();
            match op[0].as_str().unwrap() {
                "seed" => assert_eq!(
                    r.seed(key).to_bits(),
                    bits(&op[2]),
                    "{seed} op {i}: pseudoseed({key})"
                ),
                "random" => assert_eq!(
                    r.random(key).to_bits(),
                    bits(&op[2]),
                    "{seed} op {i}: pseudorandom({key})"
                ),
                "range" => {
                    let (lo, hi) = (op[2].as_i64().unwrap(), op[3].as_i64().unwrap());
                    assert_eq!(
                        r.random_range(key, lo, hi),
                        op[4].as_i64().unwrap(),
                        "{seed} op {i}: pseudorandom({key}, {lo}, {hi})"
                    );
                }
                other => panic!("unknown op {other}"),
            }
        }
    }
}

#[test]
fn predict_seed_matches() {
    for case in arr(&fixture()["predict"]) {
        let c = arr(case);
        let (key, p) = (c[0].as_str().unwrap(), c[1].as_str().unwrap());
        assert_eq!(
            rng::predict_seed(key, p).to_bits(),
            bits(&c[2]),
            "pseudoseed({key}, {p})"
        );
    }
}

#[test]
fn element_matches() {
    for case in arr(&fixture()["element"]) {
        let c = arr(case);
        let (seed, n, key) = (
            num(&c[0]),
            c[1].as_u64().unwrap() as usize,
            c[2].as_u64().unwrap() as usize,
        );
        assert_eq!(
            rng::element_index(n, seed) + 1,
            key,
            "element over {n} with seed {seed:e}"
        );
    }
}

#[test]
fn shuffle_matches() {
    for case in arr(&fixture()["shuffle"]) {
        let c = arr(case);
        let seed = num(&c[0]);
        let want: Vec<u64> = arr(&c[1]).iter().map(|v| v.as_u64().unwrap()).collect();
        let mut got: Vec<u64> = (1..=want.len() as u64).collect();
        rng::shuffle(&mut got, seed);
        assert_eq!(got, want, "shuffle of {} with seed {seed:e}", want.len());
    }
}

#[test]
fn random_string_matches() {
    for case in arr(&fixture()["random_string"]) {
        let c = arr(case);
        let seed = num(&c[0]);
        assert_eq!(
            rng::random_string(8, seed),
            c[1].as_str().unwrap(),
            "random_string(8, {seed:e})"
        );
    }
}
